verbraucher_vertragsfristgrenze <- function(fristfall=NULL, fristbeginn_am=NULL, vereinbartes_ende_am=NULL, beginnart=NULL, einordnungsnachweis=NULL) {
 faelle <- list(verbrauchsgut_neu_mindestverjaehrung=list(2,"jahre","mindestens","\u00a7476 Absatz2: gesetzlicher Verj\u00e4hrungsbeginn, zwei Jahre; nur quantitatives Mindestma\u00df vor Mangelmitteilung, Schadensersatzausnahme und besondere Vereinbarungsvoraussetzungen gesondert."),
verbrauchsgut_gebraucht_mindestverjaehrung=list(1,"jahre","mindestens","\u00a7476 Absatz2: gesetzlicher Verj\u00e4hrungsbeginn bei gebrauchter Ware, ein Jahr; Information/ausdr\u00fcckliche gesonderte Vereinbarung und Schadensersatzausnahme gesondert."),
immobiliardarlehen_bedenkzeit=list(7,"tage","mindestens","\u00a7495 Absatz3: \u00dcbergabe des Vertragsangebots im qualifizierten Fall ohne Widerrufsrecht nach Absatz2; mindestens sieben Tage Bedenkzeit."),
allgemeindarlehen_geberkuendigung=list(2,"monate","mindestens","\u00a7499 Absatz1: Zugang der Geberk\u00fcndigung bei unbestimmter Vertragslaufzeit; mindestens zwei Monate, keine gesamte Vereinbarungs-/K\u00fcndigungswirksamkeit."),
allgemeindarlehen_nehmerkuendigung=list(1,"monate","hoechstens","\u00a7500 Absatz1: Zugang der Nehmerk\u00fcndigung bei unbestimmter R\u00fcckzahlungszeit; vereinbarte Frist h\u00f6chstens ein Monat, ohne Fristvereinbarung keine Wartefrist."),
zahlungsdienst_nutzerkuendigung=list(1,"monate","hoechstens","\u00a7675h Absatz1: Zugang der Nutzerk\u00fcndigung; vereinbarte Frist h\u00f6chstens ein Monat, ohne Fristvereinbarung keine Wartefrist."),
zahlungsdienst_leisterkuendigung=list(2,"monate","mindestens","\u00a7675h Absatz2: Zugang der Dienstleisterk\u00fcndigung bei unbestimmtem Rahmenvertrag und vereinbartem K\u00fcndigungsrecht; mindestens zwei Monate."),
ueberziehung_laufzeit_504=list(3,"monate","hoechstens","\u00a7504II: Auszahlung im qualifizierten Allgemein-Verbraucherdarlehen mit \u00dcberziehungsm\u00f6glichkeit; vereinbarte Laufzeit h\u00f6chstens drei Monate nach Auszahlung. Nur numerischer Teil des Anwendungsbereichs. Alternative fristlose K\u00fcndbarkeit des Darlehensgebers und weitere Voraussetzungen zu Kosten, Zinsf\u00e4lligkeit und Vertragsmitteilung gesondert; keine automatische Ausnahme s\u00e4mtlicher Schutzvorschriften."))
 faelle[["agb_sonstige_maengel_mindestverjaehrung"]] <- list(1,"jahre","mindestens","\u00a7309Nr8bff: sonstige qualifizierte M\u00e4ngelf\u00e4lle bei neu hergestellten Sachen/Werkleistungen, gesetzlicher Verj\u00e4hrungsbeginn und mindestens ein Jahr. F\u00e4lle438I2/634aI2 und andere strengere Regeln nicht auf ein Jahr reduzieren. Nur numerische Untergrenze, keine automatische Wirksamkeit oder Verl\u00e4ngerung einer unwirksamen Klausel.")
 faelle[["gastschulaufenthalt_dreimonatsdauer"]] <- list(3,"monate","mindestens","\u00a7651uI: mindestens dreimonatiger qualifizierter Gastschulaufenthalt. Nur numerischer Dauertest; k\u00fcrzere Aufenthalte oder Praktika k\u00f6nnen durch Vereinbarung ebenfalls erfasst sein. Schulbesuch/Gastfamilie/Aufnahmeland und weitere Voraussetzungen gesondert. Keine automatische Unwirksamkeit eines k\u00fcrzeren Vertrags.")
 faelle[["agb_kuendigungsmonat_erstlaufzeit"]] <- list(1,"monate","hoechstens","\u00a7309Nr9c: numerische H\u00f6chstl\u00e4nge der K\u00fcndigungsfrist vor Ende der zun\u00e4chst vorgesehenen Vertragsdauer. fristbeginn_am ist hier der vertraglich sp\u00e4teste K\u00fcndigungseingangstag, vereinbartes_ende_am der letzte eingeschlossene Erstlaufzeittag. Ab dieser K\u00fcndigungsgrenze darf h\u00f6chstens ein Kalendermonat bis Tagesablauf des Vertragsendes liegen. Keine automatische AGB-Wirksamkeitsentscheidung; Klauselanwendbarkeit, Ausnahmen und Bedeutung der vereinbarten Termine rechtlich qualifizieren. Nicht die K\u00fcndigungsfrist einer anschlie\u00dfenden unbefristeten Verl\u00e4ngerung nachNr9b.")
 faelle[["kurzdarlehen_dreimonatsdauer_491"]] <- list(3,"monate","hoechstens","\u00a7491II Nr3: qualifizierter Beginn der R\u00fcckzahlungsfrist als Ereignis, rechtlich vereinbarter sp\u00e4tester vollst\u00e4ndiger R\u00fcckzahlungstag h\u00f6chstens drei Kalendermonate sp\u00e4ter. Geringe Kosten sind zus\u00e4tzlich rechtlich zu bewerten; keine erfundene EUR-/Prozentgrenze und kein automatischer Ausschluss s\u00e4mtlicher Verbraucherschutzrechte. Nicht blo\u00df erste Rate oder tats\u00e4chlicher freiwilliger R\u00fcckzahlungstag.")
 .auswahl(fristfall, "fristfall", names(faelle))
 beginn <- .datum(fristbeginn_am, "fristbeginn_am")
 ende <- .datum(vereinbartes_ende_am, "vereinbartes_ende_am")
 .auswahl(beginnart, "beginnart", c("ereignis","tagesbeginn"))
 .text(einordnungsnachweis,"einordnungsnachweis")
 if(ende < beginn) .fehler("vereinbartes_ende_am","Vereinbartes Ende darf nicht vor dem Fristbeginn liegen.")
 if(!startsWith(fristfall,"verbrauchsgut_") && !(fristfall %in% c("agb_sonstige_maengel_mindestverjaehrung","gastschulaufenthalt_dreimonatsdauer")) && beginnart != "ereignis") .fehler("beginnart","Dieser Fristfall setzt einen qualifizierten Ereignisbeginn voraus.")
 fall <- faelle[[fristfall]]
 grenze <- .frist(fristbeginn_am,fall[[1]],fall[[2]],beginnart)
 richtung <- fall[[3]]
 innerhalb <- if(richtung == "mindestens") ende >= grenze else ende <= grenze
 eingaben <- list(fristfall=fristfall,fristbeginn_am=fristbeginn_am,vereinbartes_ende_am=vereinbartes_ende_am,beginnart=beginnart,einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(list(gesetzliches_grenzdatum=.iso(grenze),vergleichsrichtung=richtung,numerische_fristgrenze_eingehalten=innerhalb),"datum_und_wahrheitswert","BGB_VERBRAUCHER_VERTRAGSFRISTGRENZE",eingaben,list(list(operation="Gesetzliche Mindest- oder H\u00f6chstdauer mit vorhandenem Kalenderkern berechnen und vereinbartes Ende einschlie\u00dflich gegen Grenzdatum vergleichen")),eingaben)
 ergebnis$annahmen <- list("Rechtlich qualifizierter gesetzlicher Beginn/Erkl\u00e4rungszugang und Anwendungsfall; feste lokale BGB-Fassung.")
 ergebnis$hinweise <- list("Nur numerische Vereinbarungsgrenze, kein automatisch wirksames Vertragsende oder vollst\u00e4ndiger Verj\u00e4hrungsablauf. Unzul\u00e4ssige Vereinbarung wird nicht automatisch gek\u00fcrzt oder verl\u00e4ngert. Kalender-/Hemmungskorrekturen und andere Wirksamkeitsgr\u00fcnde gesondert. Ende bezeichnet jeweils den letzten eingeschlossenen Tag bis Tagesablauf. Keine pauschale365-Tage-Jahresrechnung.",fall[[4]])
 ergebnis
}
